UPDATE resource_entity r SET name = v.name, status = v.status, owner_service_code = #{owner}, updated_at = #{updatedAt} FROM (VALUES
(CAST(#{r.id} AS BIGINT), CAST(#{r.name} AS VARCHAR), CAST(#{r.status} AS INT))
) AS v(id, name, status) WHERE r.id = v.id AND r.tenant_id = #{tenantId} AND r.delete_flag = 0

